import { motion, useInView } from "framer-motion";
import { useRef } from "react";
import { Code, Database, Globe, Server } from "lucide-react";

const skills = [
  {
    category: "Frontend",
    description: "Crafting beautiful, responsive, and high-performance user interfaces with modern web standards.",
    icon: <Globe />,
    items: [
      { name: "React", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/react/react-original.svg" },
      { name: "JavaScript", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/javascript/javascript-original.svg" },
      { name: "HTML5", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/html5/html5-original.svg" },
      { name: "CSS3", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/css3/css3-original.svg" },
      { name: "Bootstrap", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/bootstrap/bootstrap-original.svg" },
      { name: "Tailwind", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/tailwindcss/tailwindcss-original.svg" }
    ]
  },
  {
    category: "Backend",
    description: "Developing robust backend logic, secure RESTful APIs, and scalable server-side environments.",
    icon: <Server />,
    items: [
      { name: "Node.js", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/nodejs/nodejs-original.svg" },
      { name: "Express", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/express/express-original.svg" },
      { name: "Java", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/java/java-original.svg" }
    ]
  },
  {
    category: "Database",
    description: "Structuring, optimizing, and managing high-speed relational and non-relational storage engines.",
    icon: <Database />,
    items: [
      { name: "MySQL", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/mysql/mysql-original.svg" },
      { name: "MongoDB", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/mongodb/mongodb-original.svg" }
    ]
  },
  {
    category: "Tools",
    description: "Utilizing industrial version control systems, environments, and dev tools for maximum output.",
    icon: <Code />,
    items: [
      { name: "Git", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/git/git-original.svg" },
      { name: "VS Code", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/vscode/vscode-original.svg" },
      { name: "Docker", logo: "https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/docker/docker-original.svg" }
    ]
  }
];

const Skills = () => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });

  return (
    <section id="skills" className="skills-section" ref={ref}>
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        animate={isInView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.6 }}
      >
        Skills & Technologies
      </motion.h2>

      <div className="skills-grid">
        {skills.map((skill, index) => (
          <motion.div
            key={skill.category}
            initial={{ opacity: 0, y: 50, rotateY: -10 }}
            animate={isInView ? { opacity: 1, y: 0, rotateY: 0 } : {}}
            transition={{ duration: 0.6, delay: index * 0.12 }}
            whileHover={{ scale: 1.03, rotateY: 4 }}
            whileTap={{ scale: 0.98 }}
            className={`skill-card ${skill.category.toLowerCase()}-theme`}
          >
            <div className="card-inner">
              <div className="card-header-row">
                <div className="skill-icon-container">{skill.icon}</div>
                <div className="skill-title-group">
                  <h3>{skill.category}</h3>
                  <span className="skill-badge">{skill.items.length} Techs</span>
                </div>
              </div>
              <p className="skill-desc">{skill.description}</p>
              <div className="skill-tags">
                {skill.items.map((item, i) => (
                  <motion.span
                    key={item.name}
                    className="tag"
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={isInView ? { opacity: 1, scale: 1 } : {}}
                    transition={{ delay: index * 0.12 + i * 0.04 }}
                  >
                    <img 
                      src={item.logo} 
                      alt={item.name} 
                      className={`skill-logo ${item.name === "Express" ? "invert" : ""}`} 
                    />
                    {item.name}
                  </motion.span>
                ))}
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </section>
  );
};

export default Skills;
